+fn resolve_existing(root: &Utf8Path, relative: &Utf8Path, check: &str) -> Result<ResolvedPath, ImplementationContextFailure> {
+    let absolute = fs::canonicalize(root.join(relative)).map_err(|error| {
+        failure(
+            if error.kind() == io::ErrorKind::NotFound {
+                ContextErrorCode::MissingSource
+            } else {
+                ContextErrorCode::FilesystemError
+            },
+            check,
+            Some(relative.to_owned()),
+            "required source cannot be resolved",
+        )
+    })?;
+    if !absolute.starts_with(root) {
+        return Err(failure(
+            ContextErrorCode::UnsafePath,
+            check,
+            None,
+            "resolved source escapes the workspace",
+        ));
+    }
+    let absolute = Utf8PathBuf::from_path_buf(absolute).map_err(|_| {
+        failure(ContextErrorCode::UnsafePath, check, None, "resolved source path is not valid UTF-8")
+    })?;
+    let relative = absolute.strip_prefix(root).map_err(|_| {
+        failure(ContextErrorCode::UnsafePath, check, None, "resolved source is outside the workspace")
+    })?.to_owned();
+    Ok(ResolvedPath { absolute, relative })
+}
