+fn safe_relative_path(value: &str, check: &str) -> Result<Utf8PathBuf, ImplementationContextFailure> {
+    let path = Path::new(value);
+    let portable_drive = value.as_bytes().get(1) == Some(&b':')
+        && value.as_bytes().first().is_some_and(u8::is_ascii_alphabetic);
+    if value.is_empty()
+        || value.contains('\\')
+        || path.is_absolute()
+        || portable_drive
+        || path.components().any(|component| !matches!(component, Component::Normal(_)))
+    {
+        return Err(failure(ContextErrorCode::UnsafePath, check, None, "path must be workspace-relative and traversal-free"));
+    }
+    Ok(Utf8PathBuf::from(value))
+}
